def pick_examples(pool, per_label):
    groups = {}
    for text, label in pool:
        groups.setdefault(label, []).append((text, label))
    result = []
    for i in range(per_label):
        for label in groups:
            if i < len(groups[label]):
                result.append(groups[label][i])
    return result
